import sys
import json
from collections import Counter, defaultdict

import h5py


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def dataset_to_list(obj):
    values = obj[()]
    if getattr(values, "shape", ()) == ():
        return [decode_one(values)]
    return decode_array(values)


def read_dataframe_group(group):
    columns_attr = group.attrs.get("column-order", [])
    columns = decode_array(columns_attr)
    index_name = decode_one(group.attrs.get("_index", "_index"))
    out = {}
    if index_name in group:
        out[index_name] = read_column(group[index_name])
    for col in columns:
        if col in group:
            out[col] = read_column(group[col])
    return out, index_name, columns


def read_column(obj):
    if isinstance(obj, h5py.Dataset):
        return dataset_to_list(obj)
    if isinstance(obj, h5py.Group):
        encoding = decode_one(obj.attrs.get("encoding-type", ""))
        if "categories" in obj and "codes" in obj:
            categories = dataset_to_list(obj["categories"])
            codes = obj["codes"][()]
            vals = []
            for code in codes:
                code = int(code)
                vals.append(None if code < 0 else categories[code])
            return vals
        if encoding == "nullable-string-array" and "values" in obj:
            return dataset_to_list(obj["values"])
        if "values" in obj and isinstance(obj["values"], h5py.Dataset):
            return dataset_to_list(obj["values"])
    return []


def summarize_columns(table):
    summaries = {}
    for col, values in table.items():
        clean = ["<NA>" if v is None else str(v) for v in values]
        counts = Counter(clean)
        summaries[col] = {
            "n": len(clean),
            "unique": len(counts),
            "top": counts.most_common(12),
        }
    return summaries


def candidate_columns(table, needles):
    out = []
    lower_needles = [n.lower() for n in needles]
    for col, values in table.items():
        name_hit = any(n in col.lower() for n in lower_needles)
        vals = {str(v) for v in values if v is not None}
        value_hit = any(t in vals for t in TARGETS)
        if name_hit or value_hit:
            out.append(col)
    return out


def values_for_targets(ref_obs):
    evidence = []
    columns_with_target_values = []
    guide_like = candidate_columns(ref_obs, ["guide", "grna", "sgrna", "protospacer"])
    target_like = candidate_columns(ref_obs, ["target", "gene", "perturb", "knock", "guide_target"])
    for target_col in target_like:
        target_values = ref_obs.get(target_col, [])
        present = set(str(v) for v in target_values if v is not None)
        if not any(t in present for t in TARGETS):
            continue
        columns_with_target_values.append(target_col)
        for guide_col in guide_like:
            guide_values = ref_obs.get(guide_col, [])
            by_target = {}
            for target in TARGETS:
                ctr = Counter()
                for tv, gv in zip(target_values, guide_values):
                    if str(tv) == target and gv is not None:
                        ctr[str(gv)] += 1
                by_target[target] = ctr.most_common()
            evidence.append((target_col, guide_col, by_target))
    return guide_like, target_like, columns_with_target_values, evidence


def choose_answer(evidence):
    for target_col, guide_col, by_target in evidence:
        chosen = []
        ok = True
        for target in TARGETS:
            rows = by_target.get(target, [])
            if len(rows) != 1:
                ok = False
                break
            chosen.append(rows[0][0])
        if ok:
            return target_col, guide_col, chosen
    return None


def write_report(path, ref_path, query_path):
    with h5py.File(ref_path, "r") as ref, h5py.File(query_path, "r") as query:
        ref_obs, ref_index, ref_cols = read_dataframe_group(ref["obs"])
        query_obs, query_index, query_cols = read_dataframe_group(query["obs"])
        guide_like, target_like, target_value_cols, evidence = values_for_targets(ref_obs)
        selected = choose_answer(evidence)

        query_guide_presence = {}
        if selected:
            _, guide_col, chosen = selected
            if guide_col in query_obs:
                qvals = Counter(str(v) for v in query_obs[guide_col] if v is not None)
                query_guide_presence = {g: qvals.get(g, 0) for g in chosen}

        with open(path, "w", encoding="utf-8") as handle:
            handle.write("# AnnData metadata diagnostic\n")
            handle.write("targets\t" + ",".join(TARGETS) + "\n")
            handle.write("ref_obs_index\t" + str(ref_index) + "\n")
            handle.write("ref_obs_columns\t" + json.dumps(ref_cols) + "\n")
            handle.write("query_obs_index\t" + str(query_index) + "\n")
            handle.write("query_obs_columns\t" + json.dumps(query_cols) + "\n")
            handle.write("ref_guide_like_columns\t" + json.dumps(guide_like) + "\n")
            handle.write("ref_target_like_columns\t" + json.dumps(target_like) + "\n")
            handle.write("ref_columns_containing_requested_targets\t" + json.dumps(target_value_cols) + "\n")
            handle.write("ref_column_summaries\t" + json.dumps(summarize_columns(ref_obs), sort_keys=True) + "\n")
            handle.write("# candidate guide-target counts\n")
            for target_col, guide_col, by_target in evidence:
                handle.write("pair\t%s\t%s\n" % (target_col, guide_col))
                for target in TARGETS:
                    handle.write("counts\t%s\t%s\n" % (target, json.dumps(by_target.get(target, []))))
            if selected:
                target_col, guide_col, chosen = selected
                handle.write("selected_target_column\t" + target_col + "\n")
                handle.write("selected_guide_column\t" + guide_col + "\n")
                handle.write("query_selected_guide_counts\t" + json.dumps(query_guide_presence, sort_keys=True) + "\n")
                handle.write("answer\t" + ",".join(chosen) + "\n")
            else:
                handle.write("answer\tUNRESOLVED\n")


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: perturb_guide_map.py REF_H5AD QUERY_H5AD REPORT_TXT")
    write_report(sys.argv[3], sys.argv[1], sys.argv[2])

