import sys
import json
from collections import Counter

import h5py
import numpy as np
from scipy import sparse


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def dataset_to_list(obj):
    values = obj[()]
    if getattr(values, "shape", ()) == ():
        return [decode_one(values)]
    return decode_array(values)


def read_column(obj):
    if isinstance(obj, h5py.Dataset):
        return dataset_to_list(obj)
    if isinstance(obj, h5py.Group):
        if "categories" in obj and "codes" in obj:
            categories = dataset_to_list(obj["categories"])
            vals = []
            for code in obj["codes"][()]:
                code = int(code)
                vals.append(None if code < 0 else categories[code])
            return vals
        if "values" in obj and isinstance(obj["values"], h5py.Dataset):
            return dataset_to_list(obj["values"])
    return []


def read_dataframe_group(group):
    columns_attr = group.attrs.get("column-order", [])
    columns = decode_array(columns_attr)
    index_name = decode_one(group.attrs.get("_index", "_index"))
    out = {}
    if index_name in group:
        out[index_name] = read_column(group[index_name])
    for col in columns:
        if col in group:
            out[col] = read_column(group[col])
    return out, index_name, columns


def read_x(handle):
    x = handle["X"]
    if isinstance(x, h5py.Dataset):
        return np.asarray(x[()])
    encoding = str(decode_one(x.attrs.get("encoding-type", ""))).lower()
    shape = tuple(int(v) for v in x.attrs.get("shape", x["shape"][()] if "shape" in x else ()))
    data = x["data"][()]
    indices = x["indices"][()]
    indptr = x["indptr"][()]
    if "csc" in encoding:
        return sparse.csc_matrix((data, indices, indptr), shape=shape)
    return sparse.csr_matrix((data, indices, indptr), shape=shape)


def first_index(names):
    out = {}
    for i, name in enumerate(names):
        out.setdefault(str(name), i)
    return out


class SimpleAnnData:
    def __init__(self, path):
        self.path = path
        self.handle = h5py.File(path, "r")
        self.X = read_x(self.handle)
        self.obs, self.obs_index, self.obs_columns = read_dataframe_group(self.handle["obs"])
        self.var, self.var_index, self.var_columns = read_dataframe_group(self.handle["var"])
        self.var_names = [str(v) for v in self.var[self.var_index]]
        self.var_index_map = first_index(self.var_names)
        self.shape = self.X.shape

    def close(self):
        self.handle.close()


def to_1d(x):
    if sparse.issparse(x):
        x = x.toarray()
    return np.asarray(x).reshape(-1)


def mean_x(adata, mask, gene_idx=None):
    rows = np.asarray(mask, dtype=bool)
    if gene_idx is None:
        sub = adata.X[rows, :]
    elif isinstance(gene_idx, (list, tuple, np.ndarray)):
        sub = adata.X[rows, :][:, gene_idx]
    else:
        sub = adata.X[rows, gene_idx]
    return to_1d(sub.mean(axis=0))


def guide_values(adata):
    return np.asarray([str(v) for v in adata.obs["guide"]])


def guide_counts(adata):
    return Counter(guide_values(adata))


def is_nt(value):
    return value.startswith("NT") or value == "NT"


def nt_mask(adata):
    return np.asarray([is_nt(v) for v in guide_values(adata)], dtype=bool)


def non_nt_guides(adata):
    return sorted([g for g in set(guide_values(adata)) if not is_nt(g)])


def pearson(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    ok = np.isfinite(a) & np.isfinite(b)
    a = a[ok]
    b = b[ok]
    if a.size < 3:
        return float("nan")
    a = a - a.mean()
    b = b - b.mean()
    denom = np.sqrt(np.dot(a, a) * np.dot(b, b))
    if denom == 0:
        return float("nan")
    return float(np.dot(a, b) / denom)


def effect_by_guide(adata, guides, common_idx):
    vals = guide_values(adata)
    control = mean_x(adata, nt_mask(adata), common_idx)
    effects = {}
    ns = {}
    for guide in guides:
        mask = vals == guide
        ns[guide] = int(mask.sum())
        effects[guide] = mean_x(adata, mask, common_idx) - control
    return effects, ns


def jsonable_rows(rows):
    out = []
    for row in rows:
        out.append([None if isinstance(v, float) and np.isnan(v) else v for v in row])
    return out


def write_report(ref_path, query_path, out_path):
    ref = SimpleAnnData(ref_path)
    query = SimpleAnnData(query_path)
    try:
        common = sorted(set(ref.var_index_map).intersection(set(query.var_index_map)))
        ref_common_idx = [ref.var_index_map[g] for g in common]
        query_common_idx = [query.var_index_map[g] for g in common]

        ref_guides = guide_values(ref)
        ref_targets = np.asarray([str(v) for v in ref.obs["target_gene"]])
        query_guides = guide_values(query)

        ref_counts = guide_counts(ref)
        query_counts = guide_counts(query)
        query_non_nt = non_nt_guides(query)
        ref_control = mean_x(ref, nt_mask(ref), ref_common_idx)
        query_effects, query_ns = effect_by_guide(query, query_non_nt, query_common_idx)

        target_evidence = {}
        answer = []

        for target in TARGETS:
            rows = ref_guides[ref_targets == target]
            ref_guide_counts = Counter(rows)
            ref_guide = ref_guide_counts.most_common(1)[0][0]

            ref_effect = mean_x(ref, ref_guides == ref_guide, ref_common_idx) - ref_control
            top_n = min(800, len(common))
            top_idx = np.argsort(np.abs(ref_effect))[-top_n:]

            corr_rows = []
            corr_top_rows = []
            for guide in query_non_nt:
                effect = query_effects[guide]
                corr_rows.append((guide, query_ns[guide], pearson(ref_effect, effect)))
                corr_top_rows.append((guide, query_ns[guide], pearson(ref_effect[top_idx], effect[top_idx])))
            corr_rows.sort(key=lambda x: (-np.nan_to_num(x[2], nan=-2.0), x[0]))
            corr_top_rows.sort(key=lambda x: (-np.nan_to_num(x[2], nan=-2.0), x[0]))

            target_gene_rows = []
            if target in query.var_index_map:
                qi = query.var_index_map[target]
                control_mean = float(mean_x(query, nt_mask(query), qi)[0])
                for guide in query_non_nt:
                    mask = query_guides == guide
                    guide_mean = float(mean_x(query, mask, qi)[0])
                    target_gene_rows.append(
                        (guide, int(mask.sum()), guide_mean, guide_mean - control_mean)
                    )
                target_gene_rows.sort(key=lambda x: (x[3], x[0]))

            selected = target_gene_rows[0][0] if target_gene_rows else corr_top_rows[0][0]
            answer.append(selected)
            target_evidence[target] = {
                "ref_guide_counts": ref_guide_counts.most_common(),
                "selected_ref_guide": ref_guide,
                "query_target_gene_lowest_delta_top10": target_gene_rows[:10],
                "query_signature_corr_all_top10": corr_rows[:10],
                "query_signature_corr_ref_top800abs_top10": corr_top_rows[:10],
                "selected_query_guide": selected,
            }

        with open(out_path, "w", encoding="utf-8") as handle:
            handle.write("ref_shape\t%s\n" % (ref.shape,))
            handle.write("query_shape\t%s\n" % (query.shape,))
            handle.write("common_gene_count\t%d\n" % len(common))
            handle.write("ref_obs_columns\t%s\n" % json.dumps(ref.obs_columns))
            handle.write("query_obs_columns\t%s\n" % json.dumps(query.obs_columns))
            handle.write("ref_var_index\t%s\n" % ref.var_index)
            handle.write("query_var_index\t%s\n" % query.var_index)
            handle.write("ref_guide_counts_top\t%s\n" % json.dumps(ref_counts.most_common(20)))
            handle.write("query_guide_counts_top\t%s\n" % json.dumps(query_counts.most_common(50)))
            for target in TARGETS:
                ev = target_evidence[target]
                handle.write("target\t%s\n" % target)
                handle.write("ref_guide_counts\t%s\n" % json.dumps(ev["ref_guide_counts"]))
                handle.write("selected_ref_guide\t%s\n" % ev["selected_ref_guide"])
                handle.write(
                    "query_target_gene_lowest_delta_top10\t%s\n"
                    % json.dumps(jsonable_rows(ev["query_target_gene_lowest_delta_top10"]))
                )
                handle.write(
                    "query_signature_corr_all_top10\t%s\n"
                    % json.dumps(jsonable_rows(ev["query_signature_corr_all_top10"]))
                )
                handle.write(
                    "query_signature_corr_ref_top800abs_top10\t%s\n"
                    % json.dumps(jsonable_rows(ev["query_signature_corr_ref_top800abs_top10"]))
                )
                handle.write("selected_query_guide\t%s\n" % ev["selected_query_guide"])
            handle.write("answer\t%s\n" % ",".join(answer))
    finally:
        ref.close()
        query.close()


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: perturb_signature_align.py REF_H5AD QUERY_H5AD REPORT_TXT")
    write_report(sys.argv[1], sys.argv[2], sys.argv[3])

