import sys
import json
from collections import Counter, defaultdict

import h5py
import numpy as np
from scipy import sparse
from scipy.optimize import linear_sum_assignment


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def dataset_to_list(obj):
    values = obj[()]
    if getattr(values, "shape", ()) == ():
        return [decode_one(values)]
    return decode_array(values)


def read_column(obj):
    if isinstance(obj, h5py.Dataset):
        return dataset_to_list(obj)
    if isinstance(obj, h5py.Group):
        if "categories" in obj and "codes" in obj:
            categories = dataset_to_list(obj["categories"])
            vals = []
            for code in obj["codes"][()]:
                code = int(code)
                vals.append(None if code < 0 else categories[code])
            return vals
        if "values" in obj and isinstance(obj["values"], h5py.Dataset):
            return dataset_to_list(obj["values"])
    return []


def read_dataframe_group(group):
    columns = decode_array(group.attrs.get("column-order", []))
    index_name = decode_one(group.attrs.get("_index", "_index"))
    out = {}
    if index_name in group:
        out[index_name] = read_column(group[index_name])
    for col in columns:
        if col in group:
            out[col] = read_column(group[col])
    return out, index_name, columns


def read_x(handle):
    x = handle["X"]
    if isinstance(x, h5py.Dataset):
        return np.asarray(x[()])
    encoding = str(decode_one(x.attrs.get("encoding-type", ""))).lower()
    shape = tuple(int(v) for v in x.attrs.get("shape", x["shape"][()] if "shape" in x else ()))
    data = x["data"][()]
    indices = x["indices"][()]
    indptr = x["indptr"][()]
    if "csc" in encoding:
        return sparse.csc_matrix((data, indices, indptr), shape=shape)
    return sparse.csr_matrix((data, indices, indptr), shape=shape)


def first_index(names):
    out = {}
    for i, name in enumerate(names):
        out.setdefault(str(name), i)
    return out


class SimpleAnnData:
    def __init__(self, path):
        self.handle = h5py.File(path, "r")
        self.X = read_x(self.handle)
        self.obs, self.obs_index, self.obs_columns = read_dataframe_group(self.handle["obs"])
        self.var, self.var_index, self.var_columns = read_dataframe_group(self.handle["var"])
        self.var_names = [str(v) for v in self.var[self.var_index]]
        self.var_index_map = first_index(self.var_names)
        self.shape = self.X.shape

    def close(self):
        self.handle.close()


def to_1d(x):
    if sparse.issparse(x):
        x = x.toarray()
    return np.asarray(x).reshape(-1)


def mean_x(adata, mask, gene_idx):
    rows = np.asarray(mask, dtype=bool)
    sub = adata.X[rows, :][:, gene_idx]
    return to_1d(sub.mean(axis=0))


def guide_values(adata):
    return np.asarray([str(v) for v in adata.obs["guide"]])


def is_nt(value):
    return value.startswith("NT") or value == "NT"


def nt_mask(adata):
    return np.asarray([is_nt(v) for v in guide_values(adata)], dtype=bool)


def non_nt_guides(adata):
    return sorted([g for g in set(guide_values(adata)) if not is_nt(g)])


def guide_effect_matrix(adata, guides, gene_idx):
    vals = guide_values(adata)
    control = mean_x(adata, nt_mask(adata), gene_idx)
    rows = []
    counts = {}
    for guide in guides:
        mask = vals == guide
        counts[guide] = int(mask.sum())
        rows.append(mean_x(adata, mask, gene_idx) - control)
    return np.vstack(rows), counts


def row_normalize(mat):
    mat = np.asarray(mat, dtype=float)
    mat = mat - mat.mean(axis=1, keepdims=True)
    norm = np.sqrt((mat * mat).sum(axis=1, keepdims=True))
    norm[norm == 0] = np.nan
    return mat / norm


def corr_matrix(ref_effects, query_effects, top_n=None, gene_center=False, gene_z=False):
    r = np.asarray(ref_effects, dtype=float)
    q = np.asarray(query_effects, dtype=float)
    if top_n is not None and top_n < r.shape[1]:
        score = np.var(r, axis=0) + np.var(q, axis=0)
        keep = np.argsort(score)[-top_n:]
        r = r[:, keep]
        q = q[:, keep]
    if gene_center or gene_z:
        r = r - r.mean(axis=0, keepdims=True)
        q = q - q.mean(axis=0, keepdims=True)
    if gene_z:
        rs = r.std(axis=0, keepdims=True)
        qs = q.std(axis=0, keepdims=True)
        keep = (rs.reshape(-1) > 0) & (qs.reshape(-1) > 0)
        r = r[:, keep] / rs[:, keep]
        q = q[:, keep] / qs[:, keep]
    rn = row_normalize(r)
    qn = row_normalize(q)
    cm = np.matmul(rn, qn.T)
    cm[~np.isfinite(cm)] = -2.0
    return cm


def assignment_for(cm, ref_guides, query_guides):
    rows, cols = linear_sum_assignment(-cm)
    out = {}
    for r, c in zip(rows, cols):
        out[ref_guides[r]] = (query_guides[c], float(cm[r, c]))
    return out


def top_for_ref(cm, ref_guides, query_guides, ref_guide, n=8):
    r = ref_guides.index(ref_guide)
    order = np.argsort(-cm[r, :])[:n]
    return [(query_guides[c], float(cm[r, c])) for c in order]


def write_report(ref_path, query_path, out_path):
    ref = SimpleAnnData(ref_path)
    query = SimpleAnnData(query_path)
    try:
        common = sorted(set(ref.var_index_map).intersection(set(query.var_index_map)))
        ref_idx = [ref.var_index_map[g] for g in common]
        query_idx = [query.var_index_map[g] for g in common]

        ref_guides_all = guide_values(ref)
        ref_targets = np.asarray([str(v) for v in ref.obs["target_gene"]])
        ref_guides = non_nt_guides(ref)
        query_guides = non_nt_guides(query)
        ref_effects, ref_counts = guide_effect_matrix(ref, ref_guides, ref_idx)
        query_effects, query_counts = guide_effect_matrix(query, query_guides, query_idx)

        guide_to_target = {}
        target_to_ref_guide = {}
        for guide in ref_guides:
            targets = ref_targets[ref_guides_all == guide]
            common_targets = Counter(targets).most_common()
            guide_to_target[guide] = common_targets[0][0]
        for target in TARGETS:
            guides = ref_guides_all[ref_targets == target]
            target_to_ref_guide[target] = Counter(guides).most_common(1)[0][0]

        configs = [
            ("raw_all", None, False, False),
            ("raw_top3000", 3000, False, False),
            ("gene_center_top3000", 3000, True, False),
            ("gene_z_top3000", 3000, True, True),
            ("gene_center_top1000", 1000, True, False),
            ("gene_z_top1000", 1000, True, True),
        ]
        results = {}
        for name, top_n, gene_center, gene_z in configs:
            cm = corr_matrix(ref_effects, query_effects, top_n, gene_center, gene_z)
            assigned = assignment_for(cm, ref_guides, query_guides)
            target_rows = {}
            for target in TARGETS:
                ref_guide = target_to_ref_guide[target]
                target_rows[target] = {
                    "ref_guide": ref_guide,
                    "assigned_query": assigned.get(ref_guide),
                    "top_query": top_for_ref(cm, ref_guides, query_guides, ref_guide),
                }
            results[name] = target_rows

        # Prefer centered top-variable-gene one-to-one alignment; raw variants
        # are reported as diagnostics to detect unstable assignments.
        preferred = "gene_center_top3000"
        answer = []
        for target in TARGETS:
            answer.append(results[preferred][target]["assigned_query"][0])

        with open(out_path, "w", encoding="utf-8") as handle:
            handle.write("ref_shape\t%s\n" % (ref.shape,))
            handle.write("query_shape\t%s\n" % (query.shape,))
            handle.write("common_gene_count\t%d\n" % len(common))
            handle.write("ref_non_nt_guides\t%s\n" % json.dumps(ref_guides))
            handle.write("query_non_nt_guides\t%s\n" % json.dumps(query_guides))
            handle.write("ref_guide_counts\t%s\n" % json.dumps(ref_counts, sort_keys=True))
            handle.write("query_guide_counts\t%s\n" % json.dumps(query_counts, sort_keys=True))
            handle.write("requested_target_ref_guides\t%s\n" % json.dumps(target_to_ref_guide, sort_keys=True))
            handle.write("guide_to_target\t%s\n" % json.dumps(guide_to_target, sort_keys=True))
            for name in [c[0] for c in configs]:
                handle.write("config\t%s\n" % name)
                for target in TARGETS:
                    handle.write("target_result\t%s\t%s\n" % (target, json.dumps(results[name][target])))
            handle.write("preferred_config\t%s\n" % preferred)
            handle.write("answer\t%s\n" % ",".join(answer))
    finally:
        ref.close()
        query.close()


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: perturb_global_align.py REF_H5AD QUERY_H5AD REPORT_TXT")
    write_report(sys.argv[1], sys.argv[2], sys.argv[3])

