import sys
import json
from collections import Counter

import h5py


TARGETS = {"PABPC1", "NUDT21", "LEO1"}


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def dataset_to_list(obj, limit=None):
    values = obj[()]
    if getattr(values, "shape", ()) == ():
        return [decode_one(values)]
    vals = decode_array(values)
    return vals if limit is None else vals[:limit]


def read_column(obj):
    if isinstance(obj, h5py.Dataset):
        return dataset_to_list(obj)
    if isinstance(obj, h5py.Group):
        if "categories" in obj and "codes" in obj:
            categories = dataset_to_list(obj["categories"])
            out = []
            for code in obj["codes"][()]:
                code = int(code)
                out.append(None if code < 0 else categories[code])
            return out
        if "values" in obj and isinstance(obj["values"], h5py.Dataset):
            return dataset_to_list(obj["values"])
    return []


def read_dataframe_group(group):
    columns = decode_array(group.attrs.get("column-order", []))
    index_name = decode_one(group.attrs.get("_index", "_index"))
    out = {}
    if index_name in group:
        out[index_name] = read_column(group[index_name])
    for col in columns:
        if col in group:
            out[col] = read_column(group[col])
    return out, index_name, columns


def describe_node(obj):
    attrs = {str(k): decode_one(v) for k, v in obj.attrs.items()}
    if isinstance(obj, h5py.Dataset):
        return {"type": "dataset", "shape": obj.shape, "dtype": str(obj.dtype), "attrs": attrs}
    return {"type": "group", "keys": list(obj.keys()), "attrs": attrs}


def write_one(handle, label, out):
    out.write("file\t%s\n" % label)
    out.write("root\t%s\n" % json.dumps(describe_node(handle), default=str))
    for key in handle.keys():
        out.write("node\t%s\t%s\n" % (key, json.dumps(describe_node(handle[key]), default=str)))
    for dfname in ["obs", "var"]:
        table, index_name, cols = read_dataframe_group(handle[dfname])
        out.write("%s_index\t%s\n" % (dfname, index_name))
        out.write("%s_columns\t%s\n" % (dfname, json.dumps(cols)))
        for col, vals in table.items():
            vals_s = [str(v) for v in vals if v is not None]
            hits = sorted(TARGETS.intersection(vals_s))
            contains = sorted([v for v in set(vals_s) if any(t in v for t in TARGETS)])[:20]
            out.write(
                "%s_col\t%s\tunique=%d\ttop=%s\ttarget_hits=%s\tcontains=%s\n"
                % (dfname, col, len(set(vals_s)), json.dumps(Counter(vals_s).most_common(8)), json.dumps(hits), json.dumps(contains))
            )


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: inspect_h5ad_structure.py REF_H5AD QUERY_H5AD REPORT_TXT")
    with h5py.File(sys.argv[1], "r") as ref, h5py.File(sys.argv[2], "r") as query:
        with open(sys.argv[3], "w", encoding="utf-8") as out:
            write_one(ref, "ref", out)
            write_one(query, "query", out)

