import sys
import json
from collections import Counter

import h5py


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def category_info(handle, column):
    obj = handle["obs"][column]
    if isinstance(obj, h5py.Group) and "categories" in obj and "codes" in obj:
        cats = decode_array(obj["categories"][()])
        codes = [int(x) for x in obj["codes"][()]]
        counts = Counter(codes)
        return {
            "categories": cats,
            "counts_by_category": [(cats[i], counts.get(i, 0)) for i in range(len(cats))],
        }
    vals = decode_array(obj[()])
    return {"values_top": Counter(vals).most_common(), "categories": []}


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: inspect_guide_categories.py REF_H5AD QUERY_H5AD REPORT_TXT")
    with h5py.File(sys.argv[1], "r") as ref, h5py.File(sys.argv[2], "r") as query:
        ref_guide = category_info(ref, "guide")
        query_guide = category_info(query, "guide")
        ref_target = category_info(ref, "target_gene")
        with open(sys.argv[3], "w", encoding="utf-8") as out:
            out.write("ref_guide_categories\t%s\n" % json.dumps(ref_guide["categories"]))
            out.write("ref_guide_counts_by_category\t%s\n" % json.dumps(ref_guide["counts_by_category"]))
            out.write("query_guide_categories\t%s\n" % json.dumps(query_guide["categories"]))
            out.write("query_guide_counts_by_category\t%s\n" % json.dumps(query_guide["counts_by_category"]))
            out.write("ref_target_categories\t%s\n" % json.dumps(ref_target["categories"]))
            out.write("ref_target_counts_by_category\t%s\n" % json.dumps(ref_target["counts_by_category"]))
            pairs = []
            for ref_cat, query_cat in zip(ref_guide["categories"], query_guide["categories"]):
                pairs.append((ref_cat, query_cat))
            out.write("category_order_pairs\t%s\n" % json.dumps(pairs))
            wanted = {}
            for ref_cat, query_cat in pairs:
                if ref_cat.startswith("PABPC1") or ref_cat.startswith("NUDT21") or ref_cat.startswith("LEO1"):
                    wanted[ref_cat] = query_cat
            out.write("wanted_by_category_order\t%s\n" % json.dumps(wanted, sort_keys=True))

