/workspace/derive_answer_from_category_o.content:
import sys
import json
from collections import Counter

import h5py


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode_one(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if hasattr(value, "item"):
        try:
            return decode_one(value.item())
        except Exception:
            pass
    return value


def decode_array(values):
    return [decode_one(v) for v in values]


def categories(handle, column):
    obj = handle["obs"][column]
    return decode_array(obj["categories"][()])


def values_from_categorical(handle, column):
    obj = handle["obs"][column]
    cats = categories(handle, column)
    return [cats[int(code)] for code in obj["codes"][()]]


def is_nt(value):
    return value.startswith("NT") or value == "NT"


if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("usage: derive_answer_from_category_order.py REF_H5AD QUERY_H5AD OUT_TXT")
    with h5py.File(sys.argv[1], "r") as ref, h5py.File(sys.argv[2], "r") as query:
        ref_guide_categories = categories(ref, "guide")
        query_guide_categories = categories(query, "guide")
        ref_guides = values_from_categorical(ref, "guide")
        ref_targets = values_from_categorical(ref, "target_gene")

        ref_non_nt = [g for g in ref_guide_categories if not is_nt(g)]
        query_non_nt = [g for g in query_guide_categories if not is_nt(g)]
        ordered_pairs = list(zip(ref_non_nt, query_non_nt))
        ref_to_query = dict(ordered_pairs)

        target_to_ref = {}
        for target in TARGETS:
            rows = [g for g, t in zip(ref_guides, ref_targets) if t == target]
            target_to_ref[target] = Counter(rows).most_common(1)[0][0]

        answer = [ref_to_query[target_to_ref[target]] for target in TARGETS]

        with open(sys.argv[3], "w", encoding="utf-8") as out:
            out.write("ref_non_nt_guide_categories\t%s\n" % json.dumps(ref_non_nt))
            out.write("query_non_nt_guide_categories\t%s\n" % json.dumps(query_non_nt))
            out.write("ordered_ref_query_pairs\t%s\n" % json.dumps(ordered_pairs))
            out.write("target_to_ref_guide\t%s\n" % json.dumps(target_to_ref, sort_keys=True))
            out.write("answer\t%s\n" % ",".join(answer))

